// nppiSum / nppiMean / nppiMean_StdDev family executor.
//
// Host-visible surface (safe for plain .cpp translation units): the entry-point
// templates are declared here and defined + explicitly instantiated in
// nppi_statistics_executor.cu.  The public wrappers are generated by
// mpp_scripts/gen_family.py (mpp_scripts/families/nppi_{sum,mean,mean_stddev}.json).
//
// Semantics (baseline NVIDIA NPP 13.4, validated by differential tests):
//   * 2D ROI sum / mean / (mean, std-dev) reduction, device scalar or per
//     channel array output (C3/C4/AC4), optional binary mask.
//   * Sum : out = per-channel sum.  8u64s accumulates into Npp64s.
//   * Mean: out = sum / pixel_count (valid-pixel count when masked).
//   * Mean_StdDev: mean and (population) standard deviation of each selected
//     channel.  Integral sources accumulate in double precision.
//   * AC4 (AlphaPreserve=true) reduces the first three channels and leaves the
//     alpha (4th) channel out of the result.
//   * Masked C1MR reduces a single channel; masked C3CMR reduces one channel
//     selected by nCOI (0-based).  Mask byte != 0 means "valid".
//   * pDeviceBuffer is scratch only; the buffer-size helpers report a size
//     sufficient for the corresponding reduction (exact bytes are not a
//     contract).
#ifndef NPPI_STATISTICS_EXECUTOR_H
#define NPPI_STATISTICS_EXECUTOR_H

#include "npp.h"

namespace nppi {
namespace statistics {

// ---------------------------------------------------------------------------
// Sum
// ---------------------------------------------------------------------------

// out = per-channel sum of the ROI.  Channels = packed channels per pixel,
// AlphaPreserve selects AC4 (reduces Channels-1, output holds those values).
template <typename D, int Channels, typename Acc, bool AlphaPreserve>
NppStatus runSum(const D *pSrc, int nSrcStep, NppiSize oSizeROI, Npp8u *pDeviceBuffer, Acc *pSum,
                 cudaStream_t stream);

// ---------------------------------------------------------------------------
// Mean
// ---------------------------------------------------------------------------

// out = per-channel mean of the ROI.
template <typename DType, int Channels, bool AlphaPreserve>
NppStatus runMean(const DType *pSrc, int nSrcStep, NppiSize oSizeROI, Npp8u *pDeviceBuffer, Npp64f *pMean,
                  cudaStream_t stream);

// Single-channel mean with a mask (C1MR).
template <typename DType>
NppStatus runMeanMasked(const DType *pSrc, int nSrcStep, const Npp8u *pMask, int nMaskStep, NppiSize oSizeROI,
                        Npp8u *pDeviceBuffer, Npp64f *pMean, cudaStream_t stream);

// Three-channel mean restricted to one channel by nCOI, with a mask (C3CMR).
template <typename DType>
NppStatus runMeanMaskedCoi(const DType *pSrc, int nSrcStep, const Npp8u *pMask, int nMaskStep, NppiSize oSizeROI,
                           int nCOI, Npp8u *pDeviceBuffer, Npp64f *pMean, cudaStream_t stream);

// ---------------------------------------------------------------------------
// Mean + StdDev
// ---------------------------------------------------------------------------

// Single-channel mean & std-dev of the ROI (C1R).
template <typename DType>
NppStatus runMeanStdDev(const DType *pSrc, int nSrcStep, NppiSize oSizeROI, Npp8u *pDeviceBuffer, Npp64f *pMean,
                        Npp64f *pStdDev, cudaStream_t stream);

// Three-channel mean & std-dev of one selected channel (C3CR).
template <typename DType>
NppStatus runMeanStdDevCoi(const DType *pSrc, int nSrcStep, NppiSize oSizeROI, int nCOI, Npp8u *pDeviceBuffer,
                           Npp64f *pMean, Npp64f *pStdDev, cudaStream_t stream);

// Single-channel mean & std-dev with a mask (C1MR).
template <typename DType>
NppStatus runMeanStdDevMasked(const DType *pSrc, int nSrcStep, const Npp8u *pMask, int nMaskStep, NppiSize oSizeROI,
                              Npp8u *pDeviceBuffer, Npp64f *pMean, Npp64f *pStdDev, cudaStream_t stream);

// Three-channel mean & std-dev of one selected channel with a mask (C3CMR).
template <typename DType>
NppStatus runMeanStdDevMaskedCoi(const DType *pSrc, int nSrcStep, const Npp8u *pMask, int nMaskStep, NppiSize oSizeROI,
                                 int nCOI, Npp8u *pDeviceBuffer, Npp64f *pMean, Npp64f *pStdDev, cudaStream_t stream);

// ---------------------------------------------------------------------------
// Min / Max / MinMax
// ---------------------------------------------------------------------------

// out = per-channel minimum of the ROI.  Channels = packed channels per pixel;
// AlphaPreserve selects AC4 (reduces Channels-1, output holds those values).
template <typename D, int Channels, bool AlphaPreserve>
NppStatus runMin(const D *pSrc, int nSrcStep, NppiSize oSizeROI, Npp8u *pDeviceBuffer, D *pMin,
                 cudaStream_t stream);

// out = per-channel maximum of the ROI.
template <typename D, int Channels, bool AlphaPreserve>
NppStatus runMax(const D *pSrc, int nSrcStep, NppiSize oSizeROI, Npp8u *pDeviceBuffer, D *pMax,
                 cudaStream_t stream);

// out = per-channel (min, max) pair of the ROI.
template <typename D, int Channels, bool AlphaPreserve>
NppStatus runMinMax(const D *pSrc, int nSrcStep, NppiSize oSizeROI, Npp8u *pDeviceBuffer, D *pMin, D *pMax,
                    cudaStream_t stream);

// ---------------------------------------------------------------------------
// MinIndx / MaxIndx (per-channel extreme value + its pixel coordinate).
// ---------------------------------------------------------------------------

// out = per-channel minimum (IsMin=true) or maximum (IsMin=false) of the ROI
// together with the (x, y) coordinate of the first (in row-major scan order)
// pixel holding that extreme.  Channels = packed channels per pixel;
// AlphaPreserve selects AC4 (reduces Channels-1, output holds those values).
// pValue / pIndexX / pIndexY each hold readCh elements on device.
template <typename D, int Channels, bool AlphaPreserve, bool IsMin>
NppStatus runExtrIndx(const D *pSrc, int nSrcStep, NppiSize oSizeROI, Npp8u *pDeviceBuffer, D *pValue, int *pIndexX,
                      int *pIndexY, cudaStream_t stream);

// ---------------------------------------------------------------------------
// MinMaxIndx (single selected channel -> scalar min/max + NppiPoint positions)
// ---------------------------------------------------------------------------

// Single-channel min & max with the position of each.  pMask may be null (then
// nMaskStep is unused); nCOI is 1-based and only meaningful for 3-channel
// inputs (Channels=3 selects channel nCOI-1).  All outputs are single scalars /
// single NppiPoint on device.
template <typename D, int Channels>
NppStatus runMinMaxIndx(const D *pSrc, int nSrcStep, const Npp8u *pMask, int nMaskStep, NppiSize oSizeROI, int nCOI,
                        D *pMinValue, D *pMaxValue, NppiPoint *pMinIndex, NppiPoint *pMaxIndex, Npp8u *pDeviceBuffer,
                        cudaStream_t stream);

// ---------------------------------------------------------------------------
// Buffer-size helpers (host side; the stream context is not needed).
// ---------------------------------------------------------------------------

NppStatus sumGetBufferHostSize(NppiSize oSizeROI, int *hpBufferSize);
NppStatus meanGetBufferHostSize(NppiSize oSizeROI, int *hpBufferSize);
NppStatus meanStdDevGetBufferHostSize(NppiSize oSizeROI, int *hpBufferSize);
NppStatus minGetBufferHostSize(NppiSize oSizeROI, int *hpBufferSize);
NppStatus maxGetBufferHostSize(NppiSize oSizeROI, int *hpBufferSize);
NppStatus minMaxGetBufferHostSize(NppiSize oSizeROI, int *hpBufferSize);
NppStatus minIndxGetBufferHostSize(NppiSize oSizeROI, int *hpBufferSize);
NppStatus maxIndxGetBufferHostSize(NppiSize oSizeROI, int *hpBufferSize);
NppStatus minMaxIndxGetBufferHostSize(NppiSize oSizeROI, int *hpBufferSize);

}  // namespace statistics
}  // namespace nppi

#endif  // NPPI_STATISTICS_EXECUTOR_H
